function calcKey(path) {
	const { sortReading: sort, sortInvertReading: sortInvert, foldersFirstReading: foldersFirst, compressedFirstReading: compressedFirst } = config;
	return sha1(`${path}|${sort}|${sortInvert}|${foldersFirst}|${compressedFirst}`);
}

function hit(key) {
	const folderThumbnails = storage.get('cacheFolderThumbnails');
	if (!folderThumbnails[key]) return;

	folderThumbnails[key].lastAccess = app.time();
	storage.setThrottle('cacheFolderThumbnails', folderThumbnails);
}

function validate(images, isPoster, forceSize = false) {
	return images.every(function (image) {
		return !!(image && image.path && image.sha);

	});
}

function get(path, forceSize = false) {
	const folderThumbnails = storage.get('cacheFolderThumbnails');
	const key = calcKey(path);

	const data = folderThumbnails[key];
	if (!data) return false;

	const isPoster = !!data?.poster?.path;
	const images = isPoster ? [data.poster] : data.images;

	if (!validate(images, isPoster, forceSize)) return false;

	hit(key);

	return {
		poster: isPoster ? data.poster : false,
		images: !isPoster ? data.images : [],
	};
}

function set(path, images) {
	const folderThumbnails = storage.get('cacheFolderThumbnails');
	const key = calcKey(path);

	const isPoster = !Array.isArray(images);

	const poster = isPoster ? { path: images.path, sha: images.sha } : { path: '', sha: '' };
	const _images = !isPoster ? images.map((img) => ({ path: img.path, sha: img.sha })) : [];

	folderThumbnails[key] = {
		lastAccess: app.time(),
		poster: {
			path: isPoster ? poster.path : '',
			sha: isPoster ? poster.sha : '',
		},
		images: _images,
	};

	storage.setThrottle('cacheFolderThumbnails', folderThumbnails);
}

function remove(path) {
	const folderThumbnails = storage.get('cacheFolderThumbnails');
	const key = calcKey(path);

	if (folderThumbnails[key]) {
		delete folderThumbnails[key];
		storage.set('cacheFolderThumbnails', folderThumbnails);
	}
}

function purge() {
	const folderThumbnails = storage.get('cacheFolderThumbnails');

	const time = app.time();
	const cacheMaxOld = config.cacheMaxOld * 60 * 60 * 24;

	for (let key in folderThumbnails) {
		if (time - folderThumbnails[key].lastAccess > cacheMaxOld)
			delete folderThumbnails[key];
	}

	storage.set('cacheFolderThumbnails', folderThumbnails);

	return;
}

module.exports = {
	get,
	set,
	remove,
	purge,
}

const {fork} = require('node:child_process');

class ChildFork
{
	fork;
	#index = 0;
	#idleTimeout;
	#key = crypto.randomUUID();
	onCloseCallback = false;
	promisses = [];
	shouldCloseOnFinish = false;

	constructor(options = {}) {

		this.fork = fork(p.join(appDir, '.dist/fork.js'));
		this.fork.on('message', (event) => this.message(event));

		this.#idleTimeout = options.idleTimeout || false;

		if(this.#idleTimeout && options.idleTimeoutInit)
			app.setDebounce(this.#key, () => this.close(), this.#idleTimeout);

	}

	message(data) {

		const arrayIndex = this.promisses.findIndex(item => item.index === data.index);
		const promise = this.promisses[arrayIndex];
		this.promisses.splice(arrayIndex, 1);

		if(data.error)
			promise.reject(data.error);
		else
			promise.resolve(data.result);

		if(this.shouldCloseOnFinish)
			this.closeOnFinish();

	}

	work(options = {}) {

		if(this.#idleTimeout)
			app.setDebounce(this.#key, () => this.close(), this.#idleTimeout);

		const index = this.#index++;

		this.fork.send({
			index: index,
			...options,
		});

		let resolve = false, reject = false;

		const promise = new Promise(function(_resolve, _reject){

			resolve = _resolve;
			reject = _reject;

		});

		this.promisses.push({
			index: index,
			resolve: resolve,
			reject: reject,
		});

		return promise;

	}

	onClose(callback) {
		this.onCloseCallback = callback;
	}

	close() {

		if(!this.fork)
			return;

		this.fork.kill();
		delete this.fork;

		if(this.onCloseCallback)
			this.onCloseCallback();
	}

	closeOnFinish() {

		if(!this.promisses.length)
			this.close();
		else
			this.shouldCloseOnFinish = true;

	}
}

let IDLE_TIMEOUT = 5000;
let JOBS_PER_CYCLE = 30;

function config(options)
{
	if(options.idleTimeout !== undefined)
		IDLE_TIMEOUT = options.idleTimeout;

	if(options.jobsPerCycle !== undefined)
		JOBS_PER_CYCLE = options.jobsPerCycle;
}

const forks = [];
let index = 0;

function pushFork()
{
	const _index = index++;
	const fork = new ChildFork({idleTimeout: IDLE_TIMEOUT, idleTimeoutInit: false});

	forks.push({
		index: _index,
		count: 0,
		fork: fork,
	});

	fork.onClose(function(){
		closeFork(_index);
	});
}

function closeFork(index)
{
	const fork = forks.find(item => item.index === index);
	if(!fork) return;

	forks.splice(forks.indexOf(fork), 1);
	fork.fork.closeOnFinish();
}

// Keep 2 forks alive to avoid delays
function createForks()
{
	const fork = forks[0] || false;

	if(fork?.count > JOBS_PER_CYCLE)
		closeFork(fork.index);

	if(!forks[0]) pushFork();
	if(!forks[1]) pushFork();
}

function getFork(count = true)
{
	createForks();

	const fork = forks[0];
	if(count) fork.count++;

	return fork.fork;
}

async function _resize() {

	const fork = getFork();

	const result = await fork.work({
		job: '_resize',
		args: [...arguments],
	});

	return;
}

async function resizeToBlob() {

	const fork = getFork();

	return fork.work({
		job: 'resizeToBlob',
		args: [...arguments],
	});

}

async function metadata() {

	const fork = getFork();

	return fork.work({
		job: 'metadata',
		args: [...arguments],
	});

}

