		fileInfoContent.style.height = height + 'px';
		fileInfoContent.style.width = 'calc(100% - ' + Math.round(height / 1.5) + 'px)';
	}
}

function resize(active = false) {
	activeResize = active;
	if (!activeResize) return;

	_resize();

	app.event(window, 'resize', _resize);
}

