		const timeout = this.config.renderTimeout || 15000;

		const fallbackPages = function() {
			return [{
				path: path,
				ids: [],
				html: htmlString,
			}];
		}

		return new Promise(async function(resolve, reject) {
			let finished = false;

			const finish = function(pages) {
				if(finished) return;
				finished = true;
				resolve(pages && pages.length ? pages : fallbackPages());
			}

			const timeoutST = setTimeout(function() {
