						this._chaptersPage.push({
							index: index + 1,
							node: child.cloneNode(true),
						});
					}
				}
				elementI++;
			}
		}

		this.calculateAndSplitParents.pop();
		return this._chaptersPage;
	}

	this.calculateAndSplit = async function(iframe, path) {

		this._chaptersPage = [];
		this._chaptersPageFirst = true;
		this._chaptersPages = [];
