	this._convertMathML = async function(parent, math) {

		let template = document.createElement('template');
		template.innerHTML = math.outerHTML.replace(/(<\/?)m:([a-z0-9]+)/ug, '$1$2');
		parent.replaceChild(template.content, math);

		return;

