				else if(tagName === 'm:math' || tagName === 'M:MATH')
				{
					let newMath = document.createElement('math');
					newMath.innerHTML = child.innerHTML.replace(/(<\/?)m:([a-z0-9]+)/ug, '$1$2');
					parent.replaceChild(newMath, child);
				}
			}
		}

		return;

	}

