function addNewDefaultCatalogs(data, changes)
{
	data.opdsCatalogs = (data.opdsCatalogs && data.opdsCatalogs.length) ? data.opdsCatalogs : [];
	let added = false;
	const existingUrls = new Set();

	for(let i = 0, len = data.opdsCatalogs.length; i < len; i++)
	{
		const url = typeof data.opdsCatalogs[i].url === 'string' ? data.opdsCatalogs[i].url.trim() : '';

		if(url)
			existingUrls.add(url);
	}

	for(let i = 0, len = defaultCatalogs.length; i < len; i++)
	{
		const catalog = defaultCatalogs[i];
		const catalogUrl = typeof catalog.url === 'string' ? catalog.url.trim() : '';
		const missing = catalogUrl && !existingUrls.has(catalogUrl);
		const shouldAdd = missing && (catalog.changes > changes || catalog.required);

		if(shouldAdd)
		{
			data.opdsCatalogs.push({
				title: catalog.title,
				subtitle: catalog.subtitle,
				url: catalog.url,
				downloadAuto: false,
				showOnLeft: false,
				logo: catalog.logo || '',
				openInBrowserOnly: !!catalog.openInBrowserOnly,
			});

			existingUrls.add(catalogUrl);
			added = true;
		}
	}

	if(added)
		storage.set('opdsCatalogs', data.opdsCatalogs);

	return data;
}

