function loadOpdsCatalogs()
{
	const catalogs = [];
	const opdsCatalogs = addNewDefaultCatalogs({opdsCatalogs: storage.get('opdsCatalogs')}, Number.MAX_SAFE_INTEGER).opdsCatalogs;
	const list = Array.isArray(opdsCatalogs) ? opdsCatalogs : [];

	for(let i = 0, len = list.length; i < len; i++)
	{
		const catalog = list[i] || {};
		const rawUrl = typeof catalog.url === 'string' ? catalog.url.trim() : '';
		const openInBrowserOnly = !!catalog.openInBrowserOnly;
		const title = (typeof catalog.title === 'string' && catalog.title.trim()) ? catalog.title : rawUrl;

		if(!rawUrl)
			continue;

		let url = rawUrl;
		let secure = /^https/.test(rawUrl);

		if(!openInBrowserOnly)
		{
			let base64 = '';

			try
			{
				base64 = opds.base64(rawUrl);
			}
			catch(error)
			{
				console.warn('Invalid OPDS catalog URL skipped:', rawUrl, error);
				continue;
			}

			url = 'opds:'+p.sep+base64;
			secure = /^https/.test(rawUrl);
			addPathName(base64, title);
		}

		const subtitle = typeof catalog.subtitle === 'string' ? catalog.subtitle : '';
		let logo = typeof catalog.logo === 'string' ? catalog.logo.trim() : '';

		if(!logo && openInBrowserOnly)
			logo = 'https://www.google.com/s2/favicons?sz=128&domain_url='+encodeURIComponent(rawUrl);

		catalogs.push({
			title: title,
			subtitle: subtitle,
			url: url,
			secure: secure,
			logo: logo,
			openInBrowserOnly: openInBrowserOnly,
		});
	}

	handlebarsContext.opdsCatalogs = catalogs;
	opdsCatalogsLoaded = true;
}

