const shaCache = {};

function sha1(string) {
	if (string.length > 1000)
		return crypto.hash('sha1', string, 'hex');
	else if (shaCache[string])
		return shaCache[string];

	return shaCache[string] = crypto.hash('sha1', string, 'hex');
}

