function asarToAsarUnpacked(path) {
	if (!/app(-(?:arm64|x64))?\.asar\.unpacked/.test(path)) {
		var pathUnpacked = path.replace(/app(-(?:arm64|x64))?\.asar/, 'app$1.asar.unpacked');

		if (fs.existsSync(pathUnpacked)) path = pathUnpacked;
	}

	return path;
}

function zoomIn() {
	var factor = electron.webFrame.getZoomFactor();

	if (factor >= 3)
		factor += 1;
	else if (factor >= 2)
		factor += 1;
	else if (factor >= 1.25)
		factor += 0.25;
	else if (factor >= 1.10)
		factor += 0.15;
	else
		factor += 0.10;

	if (factor > 5)
		factor = 5;
	else if (factor < 0.50)
		factor = 0.50;

	storage.updateVar('config', 'zoomFactor', factor);

	electron.webFrame.setZoomFactor(Math.round(factor * 100) / 100);
}

function zoomOut() {
	var factor = electron.webFrame.getZoomFactor();

	if (factor > 3)
		factor -= 1;
	else if (factor > 2)
		factor -= 1;
	else if (factor > 1.25)
		factor -= 0.25;
	else if (factor > 1.10)
		factor -= 0.15;
	else
		factor -= 0.10;

	if (factor > 5)
		factor = 5;
	else if (factor < 0.50)
		factor = 0.50;

	storage.updateVar('config', 'zoomFactor', factor);

	electron.webFrame.setZoomFactor(Math.round(factor * 100) / 100);
}

