	for (let i = 0, len = _ebook.chaptersPages[chapterIndex].length; i < len; i++) {
		let diff = Math.abs(_ebook.chaptersPages[chapterIndex][i].chapterProgress - chapterProgress);

		if (closest === false || diff < closest.diff) {
