		sum += color.m;
	}

	let index = -0.5;

	// Convert values
	for(let i = 0, len = colors.length; i < len; i++)
	{
		let color = colors[i];

		let _s = color.m

		_colors.push({
			color: (index + (color.m / 2)) / (sum - 1) * 255,
			hue: Math.round(color.h),
			saturation: Math.round(color.s * 100),
