function getAngle(p0, p1)
{
	const originX = p0.x,
		originY = p0.y,
		targetX = p1.x,
		targetY = p1.y;

	var dx = originX - targetX;
	var dy = originY - targetY;

	var theta = Math.atan2(-dy, -dx);
	theta *= 180 / Math.PI;
	if (theta < 0) theta += 360;

	return theta;
}

function changePointsAngle(p0, p1, scale = 1, reverse = false)
{
	let y = 0;
	let x = 0;

	if(reverse)
	{
		y = p0.y + ((p1.x - p0.x) * scale);
		x = p0.x - ((p1.y - p0.y) / scale);
	}
	else
	{
		y = p0.y - ((p1.x - p0.x) * scale);
		x = p0.x + ((p1.y - p0.y) / scale);
	}

	return {x: x, y: y};
}

function findLinesIntersection(p0, p1, p2, p3)
{
	const A1 = p1.y - p0.y;
	const B1 = p0.x - p1.x;
	const C1 = A1 * p0.x + B1 * p0.y;

	const A2 = p3.y - p2.y;
	const B2 = p2.x - p3.x;
	const C2 = A2 * p2.x + B2 * p2.y;

	const determinant = A1 * B2 - A2 * B1;

	if(determinant === 0)
		return null;

	const x = (C1 * B2 - C2 * B1) / determinant;
	const y = (A1 * C2 - A2 * C1) / determinant;

	return {x: x, y: y};
}

function getDistance(p0, p1)
{
	return Math.hypot(p0.x - p1.x, p0.y - p1.y);
}

function findBezierIntersection(curve, line0, line1)
{
	let lastIntersects = false;
	let lastNegative = false;
	let prevIsIntersects = false;

	let minX = Math.min(curve.points[0].x, curve.points[3].x);
	let maxX = line1.x;

	let offset = 5;
	let _i = 0;

	let direction = 0;

	for(let i = 0; i < 200; i++)
	{
		let line = {
			p1: line0,
			p2: line1,
		};

		let intersects = curve.intersects(line);
		let intersectsL = intersects.length;

		if(!lastIntersects)
		{
			if(intersectsL)
			{
				offset /= 2;
				line1.x += offset;

				lastIntersects = intersects;
				prevIsIntersects = true;
			}
			else if(direction)
			{
				if(line1.x > maxX)
				{
					offset /= 2;
					direction = 0;

					line1.x -= offset;
				}
				else
				{
					line1.x += offset;
				}
			}
			else
			{
				if(line1.x < minX)
				{
					offset /= 2;
					direction = 1;

					line1.x += offset;
				}
				else
				{
					line1.x -= offset;
				}
			}
		}
		else
		{
			if(intersectsL)
			{
				if(!prevIsIntersects) offset /= 2;
				line1.x += offset;

				lastIntersects = intersects;
				prevIsIntersects = true;
			}
			else
			{
				if(prevIsIntersects) offset /= 2;
				line1.x -= offset;

				prevIsIntersects = false;
			}
		}

		if(offset < 0.001)
			break;

		_i++;
	}

	if(lastIntersects.length)
	{
		let average = 0;

		let len = lastIntersects.length;

		for(let i = 0; i < len; i++)
		{
			average += lastIntersects[i];
		}

		return curve.get(average / len);
	}
}




























































